import React, { useState, useEffect } from 'react';
import { 
  getEntrenamientos, addEntrenamiento, updateEntrenamiento, deleteEntrenamiento,
  getAsistenciaEntrenamientos, updateAsistenciaEntrenamiento, getJugadores,
  generarPagosEntrenamiento
} from '../../database/db';
import './GestionEntrenamientos.css';

function GestionEntrenamientos() {
  const [entrenamientos, setEntrenamientos] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [editando, setEditando] = useState(null);
  const [verAsistencia, setVerAsistencia] = useState(null);
  const [jugadores, setJugadores] = useState([]);
  const [asistenciaData, setAsistenciaData] = useState([]);
  const [loading, setLoading] = useState(false);
  const [formData, setFormData] = useState({
    fecha: '',
    hora: '',
    lugar: '',
    duracion: '2 horas',
    objetivo: '',
    monto_pago: 0
  });

  useEffect(() => {
    cargarDatos();
  }, []);

  const cargarDatos = async () => {
    setLoading(true);
    try {
      const [entrenamientosData, jugadoresData] = await Promise.all([
        getEntrenamientos(),
        getJugadores()
      ]);
      setEntrenamientos(entrenamientosData);
      setJugadores(jugadoresData);
      console.log('Entrenamientos cargados:', entrenamientosData);
    } catch (error) {
      console.error('Error cargando datos:', error);
      alert('Error al cargar los datos');
    }
    setLoading(false);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    try {
      if (editando) {
        await updateEntrenamiento(editando.id, formData);
        alert('✅ Entrenamiento actualizado');
      } else {
        const nuevo = await addEntrenamiento(formData);
        if (formData.monto_pago > 0) {
          await generarPagosEntrenamiento(nuevo.id);
        }
        alert('✅ Entrenamiento agendado');
      }
      setShowForm(false);
      setEditando(null);
      setFormData({ fecha: '', hora: '', lugar: '', duracion: '2 horas', objetivo: '', monto_pago: 0 });
      await cargarDatos();
    } catch (error) {
      alert('Error: ' + error.message);
    }
    setLoading(false);
  };

  const handleDelete = async (id) => {
    if (window.confirm('¿Eliminar este entrenamiento?')) {
      try {
        await deleteEntrenamiento(id);
        await cargarDatos();
        alert('❌ Entrenamiento eliminado');
      } catch (error) {
        alert('Error al eliminar: ' + error.message);
      }
    }
  };

  const verListaAsistencia = async (entrenamiento) => {
    setLoading(true);
    try {
      const asistencia = await getAsistenciaEntrenamientos();
      const filtrada = asistencia.filter(a => a.entrenamiento_id === entrenamiento.id);
      setAsistenciaData(filtrada);
      setVerAsistencia(entrenamiento);
    } catch (error) {
      alert('Error al cargar asistencia: ' + error.message);
    }
    setLoading(false);
  };

  const cambiarEstadoAsistencia = async (entrenamientoId, jugadorId, nuevoEstado) => {
    try {
      await updateAsistenciaEntrenamiento(entrenamientoId, jugadorId, nuevoEstado);
      const asistencia = await getAsistenciaEntrenamientos();
      setAsistenciaData(asistencia.filter(a => a.entrenamiento_id === entrenamientoId));
    } catch (error) {
      alert('Error al cambiar estado: ' + error.message);
    }
  };

  const generarPagos = async (entrenamientoId, monto) => {
    if (monto > 0) {
      try {
        await generarPagosEntrenamiento(entrenamientoId);
        alert('💰 Pagos generados para todos los jugadores');
        await cargarDatos();
      } catch (error) {
        alert('Error al generar pagos: ' + error.message);
      }
    } else {
      alert('⚠️ El monto es 0, no se generaron pagos');
    }
  };

  const getEstadoBadge = (estado) => {
    const badges = {
      'apuntado': { class: 'badge-apuntado', text: '📋 Apuntado', color: '#2196F3' },
      'asistio': { class: 'badge-asistio', text: '✅ Asistió', color: '#4CAF50' },
      'falta': { class: 'badge-falta', text: '❌ Falta', color: '#f44336' },
      'no_apuntado': { class: 'badge-no', text: '⭕ No apuntado', color: '#9e9e9e' }
    };
    return badges[estado] || badges.apuntado;
  };

  const getJugadorById = (id) => jugadores.find(j => j.id === id);

  // Función para formatear fecha de forma segura
  const formatearFecha = (fecha) => {
    if (!fecha) return 'Fecha no disponible';
    try {
      const fechaObj = new Date(fecha);
      if (!isNaN(fechaObj.getTime())) {
        return fechaObj.toLocaleDateString('es-ES', { weekday: 'long', day: 'numeric', month: 'long' });
      }
      return fecha;
    } catch (e) {
      return 'Fecha inválida';
    }
  };

  if (loading && entrenamientos.length === 0) {
    return <div className="loading-container">Cargando entrenamientos...</div>;
  }

  return (
    <div className="gestion-entrenamientos">
      <div className="header-actions">
        <h2><i className="fas fa-futbol"></i> Gestionar Entrenamientos</h2>
        <button className="btn-agregar" onClick={() => { setShowForm(true); setEditando(null); }}>
          <i className="fas fa-plus"></i> <span>Agendar</span>
        </button>
      </div>

      {/* Lista de entrenamientos */}
      <div className="entrenamientos-list">
        {entrenamientos.length === 0 ? (
          <div className="empty-state">
            <i className="fas fa-calendar-alt"></i>
            <p>No hay entrenamientos programados</p>
            <button className="btn-primary" onClick={() => setShowForm(true)}>Agendar primer entrenamiento</button>
          </div>
        ) : (
          entrenamientos.map(ent => (
            <div key={ent.id} className="entrenamiento-card">
              <div className="entrenamiento-header">
                <div className="fecha-info">
                  <i className="fas fa-calendar"></i>
                  <div>
                    <h3>{formatearFecha(ent.fecha)}</h3>
                    <p><i className="fas fa-clock"></i> {ent.hora} hrs · {ent.lugar}</p>
                  </div>
                </div>
                <div className="monto-info">
                  <span className="monto">💰 ${ent.monto_pago || 0}</span>
                  <button className="btn-generar-pagos" onClick={() => generarPagos(ent.id, ent.monto_pago)}>
                    <i className="fas fa-dollar-sign"></i> Pagos
                  </button>
                </div>
              </div>
              
              <div className="entrenamiento-body">
                <div className="objetivo">
                  <i className="fas fa-bullseye"></i>
                  <strong>Objetivo:</strong> {ent.objetivo || 'No especificado'}
                </div>
                <div className="duracion">
                  <i className="fas fa-hourglass-half"></i>
                  Duración: {ent.duracion || 'No especificada'}
                </div>
              </div>
              
              <div className="entrenamiento-footer">
                <button className="btn-asistencia" onClick={() => verListaAsistencia(ent)}>
                  <i className="fas fa-clipboard-list"></i> <span>Ver Asistencia</span>
                </button>
                <button className="btn-editar" onClick={() => { 
                  setEditando(ent); 
                  setFormData({
                    fecha: ent.fecha,
                    hora: ent.hora,
                    lugar: ent.lugar,
                    duracion: ent.duracion || '2 horas',
                    objetivo: ent.objetivo || '',
                    monto_pago: ent.monto_pago || 0
                  }); 
                  setShowForm(true); 
                }}>
                  <i className="fas fa-edit"></i>
                </button>
                <button className="btn-eliminar" onClick={() => handleDelete(ent.id)}>
                  <i className="fas fa-trash"></i>
                </button>
              </div>
            </div>
          ))
        )}
      </div>

      {/* Modal Formulario */}
      {showForm && (
        <div className="modal-overlay" onClick={() => setShowForm(false)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h3>{editando ? '✏️ Editar Entrenamiento' : '📅 Agendar Entrenamiento'}</h3>
              <button className="close-btn" onClick={() => setShowForm(false)}>&times;</button>
            </div>
            <form onSubmit={handleSubmit}>
              <div className="form-row">
                <div className="form-group">
                  <label><i className="fas fa-calendar"></i> Fecha *</label>
                  <input type="date" value={formData.fecha} onChange={(e) => setFormData({...formData, fecha: e.target.value})} required />
                </div>
                <div className="form-group">
                  <label><i className="fas fa-clock"></i> Hora *</label>
                  <input type="time" value={formData.hora} onChange={(e) => setFormData({...formData, hora: e.target.value})} required />
                </div>
              </div>
              
              <div className="form-group">
                <label><i className="fas fa-map-marker-alt"></i> Lugar *</label>
                <input type="text" value={formData.lugar} onChange={(e) => setFormData({...formData, lugar: e.target.value})} placeholder="Ej: Cancha Municipal" required />
              </div>
              
              <div className="form-row">
                <div className="form-group">
                  <label><i className="fas fa-hourglass-half"></i> Duración</label>
                  <select value={formData.duracion} onChange={(e) => setFormData({...formData, duracion: e.target.value})}>
                    <option>1 hora</option><option>1.5 horas</option><option>2 horas</option><option>2.5 horas</option><option>3 horas</option>
                  </select>
                </div>
                <div className="form-group">
                  <label><i className="fas fa-dollar-sign"></i> Monto a pagar ($)</label>
                  <input type="number" value={formData.monto_pago} onChange={(e) => setFormData({...formData, monto_pago: parseInt(e.target.value) || 0})} placeholder="0 = gratis" />
                </div>
              </div>
              
              <div className="form-group">
                <label><i className="fas fa-bullseye"></i> Objetivo del entrenamiento</label>
                <textarea rows="3" value={formData.objetivo} onChange={(e) => setFormData({...formData, objetivo: e.target.value})} placeholder="Ej: Mejorar la condición física, practicar jugadas de estrategia..."></textarea>
              </div>
              
              <div className="form-buttons">
                <button type="button" className="btn-cancelar" onClick={() => setShowForm(false)}>Cancelar</button>
                <button type="submit" className="btn-guardar" disabled={loading}>
                  {loading ? <i className="fas fa-spinner fa-spin"></i> : (editando ? 'Actualizar' : 'Agendar')}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Modal Asistencia */}
      {verAsistencia && (
        <div className="modal-overlay" onClick={() => setVerAsistencia(null)}>
          <div className="modal-content large" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h3><i className="fas fa-clipboard-list"></i> Asistencia - {formatearFecha(verAsistencia.fecha)}</h3>
              <button className="close-btn" onClick={() => setVerAsistencia(null)}>&times;</button>
            </div>
            
            <div className="asistencia-resumen">
              <div className="resumen-item">
                <span>📋 Apuntados:</span>
                <strong>{asistenciaData.filter(a => a.estado === 'apuntado').length}</strong>
              </div>
              <div className="resumen-item">
                <span>✅ Asistieron:</span>
                <strong>{asistenciaData.filter(a => a.estado === 'asistio').length}</strong>
              </div>
              <div className="resumen-item">
                <span>❌ Faltaron:</span>
                <strong>{asistenciaData.filter(a => a.estado === 'falta').length}</strong>
              </div>
            </div>

            <div className="asistencia-list">
              {asistenciaData.map(a => {
                const jugador = getJugadorById(a.jugador_id);
                const badge = getEstadoBadge(a.estado);
                if (!jugador) return null;
                
                return (
                  <div key={a.id} className="asistencia-item">
                    <div className="jugador-info">
                      <span className="numero">#{jugador.numero_camiseta || '?'}</span>
                      <span className="nombre">{jugador.nombre}</span>
                      <span className="posicion">{jugador.posicion || 'Sin posición'}</span>
                    </div>
                    <div className="estado-actual">
                      <span className={badge.class}>{badge.text}</span>
                    </div>
                    <div className="acciones-asistencia">
                      <button className="btn-asistio-small" onClick={() => cambiarEstadoAsistencia(verAsistencia.id, a.jugador_id, 'asistio')}>✅</button>
                      <button className="btn-falta-small" onClick={() => cambiarEstadoAsistencia(verAsistencia.id, a.jugador_id, 'falta')}>❌</button>
                      <button className="btn-apuntado-small" onClick={() => cambiarEstadoAsistencia(verAsistencia.id, a.jugador_id, 'apuntado')}>📋</button>
                    </div>
                  </div>
                );
              })}
            </div>
            
            <div className="modal-footer">
              <button className="btn-cerrar" onClick={() => setVerAsistencia(null)}>Cerrar</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default GestionEntrenamientos;
